begin;
update public.recipes r set payload=jsonb_set(r.payload,'{tutorial}',t.tutorial,true) from jsonb_to_recordset('[{"id": "recipe-01", "tutorial": {"videoID": "lWaBh-r2ZP0", "title": "3 Minute Tomato Pasta Sauce | Jamie Oliver & Davina McCall", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=lWaBh-r2ZP0", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-02", "tutorial": {"videoID": "eJLA2RlZNq4", "title": "Pancakes | Buddy Oliver | #CookingBuddies", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=eJLA2RlZNq4", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-03", "tutorial": {"videoID": "iM_KMYulI_s", "title": "Gordon Ramsay''s perfect burger tutorial | GMA", "author": "Good Morning America", "sourceURL": "https://www.youtube.com/watch?v=iM_KMYulI_s", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-04", "tutorial": {"videoID": "1-SJGQ2HLp8", "title": "How to Make Perfect Pizza | Gennaro Contaldo", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=1-SJGQ2HLp8", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-05", "tutorial": {"videoID": "6OBoHKRQdHI", "title": "7- Minute Salmon Piccata - Seared Salmon with Lemon Butter Pan Sauce - Food Wishes", "author": "Food Wishes", "sourceURL": "https://www.youtube.com/watch?v=6OBoHKRQdHI", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-06", "tutorial": {"videoID": "cdjcz73EEtc", "title": "Steak au Poivre  \"Pepper Steak\"", "author": "Food Wishes", "sourceURL": "https://www.youtube.com/watch?v=cdjcz73EEtc", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-07", "tutorial": {"videoID": "LrKhcvZYFdQ", "title": "Easy Vegetable Soup Recipe", "author": "Inspired Taste", "sourceURL": "https://www.youtube.com/watch?v=LrKhcvZYFdQ", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-08", "tutorial": {"videoID": "vLP2CXsQGGo", "title": "Jamie''s Ministry of Food - everyday green chopped salad", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=vLP2CXsQGGo", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-09", "tutorial": {"videoID": "bJeUb8ToRIw", "title": "How to Cook Roast Chicken | Jamie Oliver", "author": "Jamie Oliver", "sourceURL": "https://www.youtube.com/watch?v=bJeUb8ToRIw", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-10", "tutorial": {"videoID": "Q3xg35pcLyo", "title": "How to Make Italian BRUSCHETTA - Easy Appetizer", "author": "Natashas Kitchen", "sourceURL": "https://www.youtube.com/watch?v=Q3xg35pcLyo", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-11", "tutorial": {"videoID": "OMqQjB4pJVY", "title": "Easy Mozzarella And Tomato Bruschetta Recipe | Mary Berry''s Quick Cooking | Mary Berry", "author": "Mary Berry", "sourceURL": "https://www.youtube.com/watch?v=OMqQjB4pJVY", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}, {"id": "recipe-12", "tutorial": {"videoID": "zyF_0hqLqHA", "title": "Mediterranean Baked Chicken Dinner (Lemon Garlic Chicken Potato Bake)", "author": "RecipeTin Eats", "sourceURL": "https://www.youtube.com/watch?v=zyF_0hqLqHA", "provider": "YouTube", "note": "A creator''s take on this dish. Ingredients and timings may differ from Toli''s recipe."}}]'::jsonb) as t(id text,tutorial jsonb) where r.id=t.id and r.owner_id is null;
select id,payload->'tutorial' as tutorial from public.recipes where id like 'recipe-%' and owner_id is null order by id;
commit;
